let filter='all',view='overview',descending=false,selected=new Set(),scanTimer,toastTimer;
const views={overview:['Fleet overview','Monitor your infrastructure. Close the gaps that matter.','grid','Fleet Overview'],scan:['Vulnerability scan','Prioritize vulnerabilities across affected environments.','scan','Vulnerability Scan'],deployments:['Patch deployments','Track rollout progress and coordinate remediation.','layers','Patch Deployments'],reports:['Compliance reports','Review fleet coverage and export the current compliance snapshot.','report','Compliance Reports'],settings:['Settings','Configure your local dashboard preferences.','settings','Settings']};
function nav(){ $('#navigation').innerHTML=Object.entries(views).map(([key,v])=>`<button data-view="${key}" class="${view===key?'active':''}" title="${v[3]}" ${view===key?'aria-current="page"':''}>${icon(v[2])}<span class="nav-text">${v[3]}</span>${key==='scan'?`<span class="nav-count">${data.filter(a=>a.status==='critical').length}</span>`:''}</button>`).join(''); }
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function filtered(){let q=$('#search').value.trim().toLowerCase();return data.filter(a=>(filter==='all'||a.status===filter)&&($('#os').value==='all'||a.os===$('#os').value)&&(!q||`${a.name} ${a.ip} ${a.cve} ${a.os} ${a.env}`.toLowerCase().includes(q))).sort((a,b)=>descending?b.name.localeCompare(a.name):a.id-b.id)}
const labels={critical:'Critical',reboot:'Pending reboot',compliant:'Compliant',deploying:'Deploying'};
function render(){nav();const critical=data.filter(a=>a.status==='critical'),running=data.filter(a=>a.status==='deploying');$('#missing').textContent=data.reduce((s,a)=>s+a.missing,0);$('#active').textContent=running.length;$('#alert-count').textContent=critical.length;$('#attention').hidden=!critical.length||!['overview','scan'].includes(view);$('#attention strong').textContent=`${critical.length} asset groups have critical vulnerabilities`;$('.summary article:nth-child(2) .metric-note span').textContent=`${critical.length} groups need attention`;$('#rollout-assets').textContent=`${running.reduce((s,a)=>s+a.assets,0)} assets in progress`;const compliance=Math.round(data.filter(a=>a.status==='compliant').reduce((s,a)=>s+a.assets,0)/1248*100);$('#health-text').textContent=`${compliance}% compliant`;
document.querySelectorAll('[data-filter]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.filter===filter));b.querySelector('span').textContent=b.dataset.filter==='all'?data.length:data.filter(a=>a.status===b.dataset.filter).length});
const items=filtered();$('#rows').innerHTML=items.length?items.map(a=>`<tr><td><input type="checkbox" data-select="${a.id}" aria-label="Select ${a.name}" ${selected.has(a.id)?'checked':''} ${a.status!=='critical'?'disabled':''}></td><td><button class="asset-name" data-detail="${a.id}">${a.name}</button><div class="asset-sub"><span class="env">${a.env}</span>${a.assets} assets</div></td><td><div class="os-name"><span class="os-symbol">${a.os==='Windows'?'⊞':'◈'}</span>${a.os}</div><div class="os-version">${a.version}</div></td><td><span class="badge ${a.status}">${a.status==='compliant'?'✓':a.status==='critical'?'!':a.status==='reboot'?'◷':'↻'} ${labels[a.status]}${a.status==='critical'?` · ${a.missing}`:''}</span>${a.status==='deploying'?`<div class="row-progress" role="progressbar" aria-label="${a.name} rollout" aria-valuenow="${a.progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${a.progress}%"></span></div><div class="status-sub">${a.progress}% deployed</div>`:`<div class="status-sub">${a.status==='critical'?a.cve:a.status==='reboot'?'Patch installed · reboot required':'All security patches applied'}</div>`}</td><td><div class="scan-date">${new Date(a.scan).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'})}</div><div class="scan-time">${new Date(a.scan).toISOString().slice(11,16)} UTC</div></td><td class="action-cell">${a.status==='critical'?`<button class="deploy" data-deploy="${a.id}">Deploy patch <span>↑</span></button>`:a.status==='reboot'?`<button class="deploy secondary" data-reboot="${a.id}">Reboot assets</button>`:a.status==='deploying'?`<button class="deploy secondary" data-detail="${a.id}">View rollout</button>`:'<span class="patched-label">✓ Up to date</span>'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No matching assets. Adjust your search or filters.</td></tr>';
$('#result-count').textContent=`Showing ${items.length} of ${data.length} asset groups`;$('#selection-count').textContent=`${selected.size} groups selected`;$('#deploy-selected').disabled=!selected.size;const eligible=items.filter(a=>a.status==='critical');$('#select-all').checked=eligible.length>0&&eligible.every(a=>selected.has(a.id));$('#select-all').indeterminate=eligible.some(a=>selected.has(a.id))&&!$('#select-all').checked;$('#select-all').disabled=!eligible.length;
$('#rollouts').innerHTML=running.length?running.map(a=>`<article class="rollout-card"><div class="rollout-top"><span class="rollout-name">${a.cve} <span style="color:#748290"> / </span> ${a.name}</span><span class="badge deploying">In progress</span></div><p>${a.os} security update · ${a.assets} assets · Rolling deployment</p><div class="progress" role="progressbar" aria-label="${a.name}" aria-valuenow="${a.progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${a.progress}%"></span></div><div class="rollout-bottom"><span>${Math.floor(a.assets*a.progress/100)} of ${a.assets} assets patched</span><strong>${a.progress}% complete</strong></div></article>`).join(''):'<div class="empty">No active rollouts. Your fleet is ready for its next deployment.</div>';if(view==='reports')renderReports();}
function changeView(v){if(!views[v])v='overview';view=v;$('#title').textContent=views[v][0];$('#subtitle').textContent=views[v][1];$('#breadcrumb').textContent=views[v][0];document.title=views[v][0]+' · PatchWarden';$('#fleet-panel').hidden=!['overview','scan'].includes(v);$('#other-panel').hidden=!['reports','settings'].includes(v);$('#rollout-section').hidden=!['overview','deployments'].includes(v);$('#scan').hidden=['reports','settings'].includes(v);if(v==='scan')filter='critical';if(v==='overview')filter='all';if(v==='settings')renderSettings();render()}
function deploy(ids){const affected=data.filter(a=>ids.includes(a.id)&&a.status==='critical');affected.forEach(a=>{a.status='deploying';a.progress=0;a.dynamic=true;selected.delete(a.id)});render();if(affected.length)notify(`Demo rollout started for ${affected.length} asset group${affected.length>1?'s':''}.`);return {started:affected.map(a=>a.name)}}
function showDetail(id){const a=data.find(x=>x.id===id);$('#detail-content').innerHTML=`<div class="eyebrow">ASSET GROUP</div><h2>${a.name}</h2><p>${a.assets} assets · ${a.env}</p>${[['Network',a.ip],['Operating system',a.os+' '+a.version],['Patch identifier',a.cve],['Status',labels[a.status]],['Missing critical patches',a.missing],...(a.status==='deploying'?[['Rollout progress',a.progress+'%']]:[])].map(([k,v])=>`<div class="detail-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p>Demonstration data. No production infrastructure is connected.</p>`;$('#detail').showModal()}
function renderReports(){const compliant=data.filter(a=>a.status==='compliant');$('#other-panel').innerHTML=`<h2>Current fleet compliance</h2><p>Snapshot generated ${new Date().toISOString().slice(0,16).replace('T',' ')} UTC</p><div class="report-row"><div><strong>Security patch coverage</strong><p>${$('#health-text').textContent}. Coverage reflects assets in fully patched groups.</p></div><span class="badge compliant">${$('#health-text').textContent}</span></div><div class="report-row"><div><strong>Fully patched asset groups</strong><p>${compliant.map(a=>a.name).join(', ')||'No fully patched groups'}</p></div><strong>${compliant.length} / 12</strong></div><div class="report-row"><div><strong>Fleet inventory report</strong><p>Asset counts, operating systems, CVEs, scan times and patch status.</p></div><button class="button" id="report-export">Export CSV</button></div>`;$('#report-export').onclick=exportCSV}
function renderSettings(){let pref={};try{pref=JSON.parse(localStorage.getItem('pw-dashboard-prefs')||'{}')}catch{}$('#other-panel').innerHTML=`<h2>Dashboard preferences</h2><p>Saved on this browser. These settings do not change production infrastructure.</p><label class="settings-label"><span>Table density<small>Choose the spacing between asset rows.</small></span><select id="density"><option value="compact">Compact</option><option value="comfortable">Comfortable</option></select></label><label class="settings-label"><span>Default operating system<small>Applied when you next open the dashboard.</small></span><select id="default-os">${['all','Ubuntu','Windows','Red Hat','Debian'].map(x=>`<option value="${x}">${x==='all'?'All operating systems':x}</option>`).join('')}</select></label><p><button class="button" id="save-settings">Save preferences</button></p>`;$('#density').value=pref.density||'compact';$('#default-os').value=pref.os||'all';$('#save-settings').onclick=()=>{try{localStorage.setItem('pw-dashboard-prefs',JSON.stringify({density:$('#density').value,os:$('#default-os').value}));applyDensity($('#density').value);notify('Dashboard preferences saved.')}catch{notify('Browser storage is unavailable. Preferences could not be saved.')}}}
function applyDensity(v){document.documentElement.style.setProperty('--density',v);let s=$('#density-style');if(!s){s=document.createElement('style');s.id='density-style';document.head.append(s)}s.textContent=v==='comfortable'?'td{padding-top:21px!important;padding-bottom:21px!important}':''}
function exportCSV(){const items=view==='reports'?data:filtered();const head=['Asset group','Asset count','Environment','OS','Version','Status','Missing critical patches','Patch identifier','Network','Last scan UTC'];const rows=items.map(a=>[a.name,a.assets,a.env,a.os,a.version,labels[a.status],a.missing,a.cve,a.ip,a.scan]);const csv=[head,...rows].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='patchwarden-fleet-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`Exported ${items.length} asset groups.`)}
$('#navigation').onclick=e=>{const b=e.target.closest('[data-view]');if(b)location.hash=b.dataset.view};window.addEventListener('hashchange',()=>changeView(location.hash.slice(1)));document.addEventListener('click',e=>{const b=e.target.closest('[data-detail],[data-deploy],[data-reboot],[data-filter]');if(!b)return;if(b.dataset.detail!==undefined)showDetail(Number(b.dataset.detail));if(b.dataset.deploy!==undefined)deploy([Number(b.dataset.deploy)]);if(b.dataset.reboot!==undefined){const a=data[Number(b.dataset.reboot)];a.status='compliant';a.missing=0;render();notify(`Demo reboot completed for ${a.name}.`)}if(b.dataset.filter){filter=b.dataset.filter;render()}});
$('#rows').onchange=e=>{if(e.target.dataset.select!==undefined){const id=Number(e.target.dataset.select);e.target.checked?selected.add(id):selected.delete(id);render()}};$('#select-all').onchange=e=>{filtered().filter(a=>a.status==='critical').forEach(a=>e.target.checked?selected.add(a.id):selected.delete(a.id));render()};$('#deploy-selected').onclick=()=>deploy([...selected]);$('#search').oninput=()=>{if(!['overview','scan'].includes(view))changeView('overview');render()};$('#os').onchange=render;$('#sort').onclick=()=>{descending=!descending;$('#sort span').textContent=descending?'↑':'↓';render()};$('#export').onclick=exportCSV;$('#all-deployments').onclick=()=>location.hash='deployments';function showCritical(){changeView('overview');filter='critical';render();$('#fleet-panel').scrollIntoView({behavior:'smooth',block:'start'})}$('#review').onclick=showCritical;$('#alerts').onclick=showCritical;$('#health').onclick=()=>{changeView('overview');filter='compliant';render()};$('#scan').onclick=()=>{const b=$('#scan');b.disabled=true;b.textContent='Scanning fleet…';clearTimeout(scanTimer);scanTimer=setTimeout(()=>{const now=new Date().toISOString();data.forEach(a=>a.scan=now);$('#sync-time').textContent='just now';b.disabled=false;b.innerHTML=icon('refresh')+'Run fleet scan';render();notify('Demo scan complete. All 1,248 assets checked.');},1800)};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
