if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_fleet_assets',description:'Read demonstration asset groups and their current patch status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({assets:data.map(a=>({id:a.id,name:a.name,status:a.status,missingPatches:a.missing}))})})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'start_demo_patch_rollouts',description:'Start simulated patch deployments for critical demo asset groups. No real servers are modified.',inputSchema:{type:'object',properties:{assetIds:{type:'array',items:{type:'integer'}}},required:['assetIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Array.isArray(input.assetIds)||!input.assetIds.length||input.assetIds.some(id=>!Number.isInteger(id)||!data.some(a=>a.id===id&&a.status==='critical')))throw new Error('Provide IDs of critical asset groups.');return deploy(input.assetIds)}})).catch(()=>{})}catch{}}
